cd /tmp && python3 - <<'PY'
import json

dvn = json.load(open('dvn.json'))
dep = json.load(open('depv2.json'))

chains = {'arc':'Arc', 'arbitrum':'Arbitrum', 'gnosis':'Gnosis'}

for ck, name in chains.items():
    print('='*70)
    print(f"CHAIN: {name} (chainKey={ck})")
    # protocol contracts
    for d in dep:
        if d.get('chainKey') == ck:
            print(f"  EID={d.get('eid')}  chainId={d.get('nativeChainId')}")
            for k in ('endpointV2','sendUln302','receiveUln302','executor','lzExecutor','readLib1002'):
                v = d.get(k)
                if v: print(f"    {k}: {v.get('address')}")
            break
    # DVNs
    push = [x for x in dvn if x.get('chainKey')==ck and not x.get('lzReadCompatible')]
    read = [x for x in dvn if x.get('chainKey')==ck and x.get('lzReadCompatible')]
    print(f"  PUSH DVNs ({len(push)}):")
    for x in sorted(push, key=lambda z: z['dvnAddress'].lower()):
        print(f"    {x['dvnAddress']}  {x['dvnDisplayName']}")
    print(f"  lzRead DVNs ({len(read)}):")
    for x in sorted(read, key=lambda z: z['dvnAddress'].lower()):
        print(f"    {x['dvnAddress']}  {x['dvnDisplayName']}")
PY

